-- Seed the exercise catalog and starter workout plans.
-- Rows reference each other by slug, never by generated id.

insert into public.exercises (slug, name, muscle_group, equipment, location, level, instructions) values
-- Chest
('barbell-bench-press', 'Barbell Bench Press', 'chest', 'barbell', 'gym', 'intermediate', 'Bench par let kar bar ko shoulder-width se pakdein. Bar ko control ke saath chest tak laayein, phir seedha upar push karein. Pair zameen par flat rakhein.'),
('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest', 'dumbbell', 'gym', 'intermediate', 'Bench ko 30-45 degree par set karein. Dumbbells upper chest ke paas se upar press karein aur dheere wapas laayein.'),
('cable-fly', 'Cable Fly', 'chest', 'cable', 'gym', 'intermediate', 'Cable handles pakad kar ek kadam aage aayein. Kohni halki mod kar haathon ko chest ke saamne milaayein, phir control se kholein.'),
('machine-chest-press', 'Machine Chest Press', 'chest', 'machine', 'gym', 'beginner', 'Seat aisi set karein ki handles chest level par hon. Handles aage push karein aur dheere wapas laayein, peeth pad se lagi rahe.'),
('push-up', 'Push-Up', 'chest', 'bodyweight', 'both', 'beginner', 'Haath shoulders se thode chaude rakhein. Body ko sir se edi tak seedha rakhte hue chest zameen ke paas laayein, phir upar push karein.'),
('incline-push-up', 'Incline Push-Up', 'chest', 'bodyweight', 'both', 'beginner', 'Haath bench, bed ya mazboot table par rakhein. Body seedhi rakh kar chest ko edge ki taraf laayein aur wapas push karein. Push-up ka aasaan version.'),
('decline-push-up', 'Decline Push-Up', 'chest', 'bodyweight', 'both', 'intermediate', 'Pair bench ya step par rakhein aur haath zameen par. Body seedhi rakh kar push-up karein. Upper chest aur shoulders par zyada zor padta hai.'),
('chest-dips', 'Chest Dips', 'chest', 'bar', 'gym', 'advanced', 'Parallel bars par body uthaayein, thoda aage jhukein aur kohni modte hue neeche jaayein jab tak shoulders mein halka stretch ho. Phir upar push karein.'),
-- Back
('lat-pulldown', 'Lat Pulldown', 'back', 'cable', 'gym', 'beginner', 'Bar ko shoulder-width se chauda pakdein. Chest upar rakh kar bar ko upper chest tak kheenchein aur dheere upar jaane dein.'),
('seated-cable-row', 'Seated Cable Row', 'back', 'cable', 'gym', 'beginner', 'Seedhe baith kar handle ko pet ki taraf kheenchein, shoulder blades ko peeche dabaayein. Control se haath aage le jaayein.'),
('barbell-row', 'Barbell Row', 'back', 'barbell', 'gym', 'intermediate', 'Ghutne halke mod kar kamar se aage jhukein, peeth seedhi rakhein. Bar ko pet ki taraf kheenchein aur dheere neeche laayein.'),
('dumbbell-row', 'One-Arm Dumbbell Row', 'back', 'dumbbell', 'gym', 'beginner', 'Ek haath aur ghutna bench par rakhein. Dusre haath se dumbbell ko kamar ki taraf kheenchein, peeth seedhi rakhein.'),
('pull-up', 'Pull-Up', 'back', 'bar', 'gym', 'advanced', 'Bar ko shoulder-width se chauda pakad kar latkein. Chin bar ke upar aane tak body upar kheenchein, phir poori tarah neeche aayein.'),
('superman', 'Superman Hold', 'back', 'bodyweight', 'home', 'beginner', 'Pet ke bal let kar haath aage failaayein. Haath, chest aur pair ek saath zameen se halka uthaayein, 2 second rokein, phir neeche laayein.'),
('reverse-snow-angel', 'Reverse Snow Angel', 'back', 'bodyweight', 'home', 'beginner', 'Pet ke bal let kar haath kamar ke paas rakhein. Chest halka utha kar haathon ko side se sir ke upar tak arc mein le jaayein aur wapas laayein.'),
-- Shoulders
('overhead-dumbbell-press', 'Overhead Dumbbell Press', 'shoulders', 'dumbbell', 'gym', 'intermediate', 'Dumbbells shoulder level par rakh kar seedhe baithein ya khade hon. Upar press karein bina kamar ko mode, phir dheere neeche laayein.'),
('lateral-raise', 'Lateral Raise', 'shoulders', 'dumbbell', 'gym', 'beginner', 'Halke dumbbells side mein pakdein. Kohni halki mod kar haath shoulder height tak side mein uthaayein, phir dheere neeche laayein.'),
('face-pull', 'Face Pull', 'shoulders', 'cable', 'gym', 'intermediate', 'Rope attachment ko face height par set karein. Rope ko chehre ki taraf kheenchein, kohniyan bahar aur upar rakhein.'),
('pike-push-up', 'Pike Push-Up', 'shoulders', 'bodyweight', 'home', 'intermediate', 'Hips upar utha kar body ko ulta V shape mein rakhein. Kohni mod kar sir ko zameen ki taraf laayein, phir wapas push karein.'),
('arm-circles', 'Arm Circles', 'shoulders', 'bodyweight', 'both', 'beginner', 'Haath side mein shoulder height par failaayein. Chhote circles aage ki taraf banaayein, phir peeche ki taraf. Warm-up ke liye accha hai.'),
-- Arms
('barbell-curl', 'Barbell Curl', 'arms', 'barbell', 'gym', 'beginner', 'Bar ko shoulder-width par neeche se pakdein. Kohni body ke paas rakh kar bar ko shoulders tak curl karein, phir dheere neeche laayein.'),
('hammer-curl', 'Hammer Curl', 'arms', 'dumbbell', 'gym', 'beginner', 'Dumbbells ko angoothe upar ki taraf rakh kar pakdein. Kohni hilaaye bina curl karein aur control se neeche laayein.'),
('triceps-pushdown', 'Triceps Pushdown', 'arms', 'cable', 'gym', 'beginner', 'Cable bar ya rope pakad kar kohni body ke paas rakhein. Haathon ko neeche seedha push karein, phir dheere upar aane dein.'),
('skull-crusher', 'Skull Crusher', 'arms', 'barbell', 'gym', 'intermediate', 'Bench par let kar EZ bar ko upar pakdein. Sirf kohni mod kar bar ko maathe ki taraf laayein, phir seedha upar karein.'),
('bench-dips', 'Bench Dips', 'arms', 'bodyweight', 'both', 'beginner', 'Mazboot kursi ya bench ke edge par haath rakhein, pair aage. Kohni peeche mod kar body neeche laayein aur wapas push karein.'),
('diamond-push-up', 'Diamond Push-Up', 'arms', 'bodyweight', 'both', 'intermediate', 'Haathon ko chest ke neeche paas rakh kar angoothe aur ungliyon se diamond banaayein. Kohni body ke paas rakh kar push-up karein.'),
-- Legs
('barbell-back-squat', 'Barbell Back Squat', 'legs', 'barbell', 'gym', 'intermediate', 'Bar ko upper back par rakhein. Chest upar rakh kar hips peeche aur neeche le jaayein jab tak thighs zameen ke parallel hon, phir edi se push karke khade hon.'),
('leg-press', 'Leg Press', 'legs', 'machine', 'gym', 'beginner', 'Pair platform par shoulder-width rakhein. Ghutne mod kar platform ko control se neeche laayein, phir push karein. Ghutne lock na karein.'),
('romanian-deadlift', 'Romanian Deadlift', 'legs', 'barbell', 'gym', 'intermediate', 'Bar ko thighs ke saamne pakdein. Ghutne halke mod kar hips peeche le jaayein, peeth seedhi rakhein, jab tak hamstrings mein stretch ho. Phir hips aage karke khade hon.'),
('bodyweight-squat', 'Bodyweight Squat', 'legs', 'bodyweight', 'both', 'beginner', 'Pair shoulder-width par rakhein. Hips peeche le jaate hue neeche baithein, chest upar rakhein, phir edi se push karke khade hon.'),
('reverse-lunge', 'Reverse Lunge', 'legs', 'bodyweight', 'both', 'beginner', 'Ek pair peeche le jaakar dono ghutne lagbhag 90 degree tak modein. Aage wale pair ki edi se push karke wapas aayein. Dono pair badal-badal kar karein.'),
('glute-bridge', 'Glute Bridge', 'legs', 'bodyweight', 'both', 'beginner', 'Peeth ke bal let kar ghutne modein, pair zameen par. Hips upar uthaayein jab tak body kandhon se ghutno tak seedhi ho, phir dheere neeche laayein.'),
('calf-raise', 'Calf Raise', 'legs', 'bodyweight', 'both', 'beginner', 'Seedhe khade hokar panjon par upar uthein, 1 second rokein, phir dheere edi neeche laayein. Balance ke liye deewar pakad sakte hain.'),
('jump-squat', 'Jump Squat', 'legs', 'bodyweight', 'home', 'advanced', 'Squat position mein neeche jaayein, phir zor se upar jump karein. Naram landing karein aur seedha agle squat mein jaayein.'),
-- Core
('plank', 'Plank', 'core', 'bodyweight', 'both', 'beginner', 'Kohni shoulders ke neeche rakh kar body ko sir se edi tak seedha rakhein. Pet tight rakhein aur hips na girne dein.'),
('side-plank', 'Side Plank', 'core', 'bodyweight', 'both', 'intermediate', 'Ek kohni par side mein let kar hips uthaayein taaki body seedhi line mein ho. Time poora hone par dusri side karein.'),
('dead-bug', 'Dead Bug', 'core', 'bodyweight', 'both', 'beginner', 'Peeth ke bal let kar haath upar aur ghutne 90 degree par. Kamar zameen se chipka kar ulta haath aur pair dheere neeche laayein, phir side badlein.'),
('bicycle-crunch', 'Bicycle Crunch', 'core', 'bodyweight', 'both', 'beginner', 'Peeth ke bal let kar haath sir ke peeche rakhein. Ulti kohni ko ulte ghutne ki taraf laate hue cycling motion karein.'),
('mountain-climber', 'Mountain Climber', 'core', 'bodyweight', 'both', 'intermediate', 'Push-up position mein ghutno ko baari-baari chest ki taraf tezi se laayein. Hips neeche aur body stable rakhein.'),
('hanging-knee-raise', 'Hanging Knee Raise', 'core', 'bar', 'gym', 'intermediate', 'Bar se latak kar ghutno ko chest ki taraf uthaayein bina jhoole. Control se neeche laayein.'),
('cable-woodchop', 'Cable Woodchop', 'core', 'cable', 'gym', 'intermediate', 'Cable ko upar set karein aur side mein khade hon. Dono haathon se handle ko diagonal mein neeche ulte ghutne tak kheenchein, torso ghumaate hue.');

